uml.text:
@startuml
class Customer
class Order {
  id : int
  total()
}
Customer "1" -- "*" Order
@enduml

@startuml
left to right direction
actor Customer
rectangle Shop {
  usecase "Browse" as Browse
  usecase "Check out" as Checkout
}
Customer --> Browse
Customer --> Checkout
@enduml

@startuml
start
:Receive order;
if (In stock?) then (yes)
  fork
    :Pack;
  fork again
    :Invoice;
  end fork
  :Ship;
else (no)
  :Back-order;
endif
stop
@enduml

@startuml
node "Web server" {
  artifact "app.war" as App
}
node "Database server" {
  database Orders
}
App --> Orders
@enduml

@startuml
object alice {
  name = "Alice"
}
object order1 {
  total = 42
}
alice --> order1 : placed
@enduml

@startuml
robust "Door" as D
concise "User" as U
@0
D is Closed
U is Idle
@5
D is Opening
U is Waiting
@10
D is Open
U is Entering
@enduml
